local function GetAdaptiveSpeed()
 local boost = math.clamp(tonumber(Config.BoostLevel) or Config.MinBoost, Config.MinBoost, Config.MaxBoost)
 return Config.BaseWalkSpeed + (boost * 40)
end

local TreadmillKeywords = {
