local VXZHomeImage = ""
pcall(function()
    local imageFile = "Vxz_Home_Image.webp"
    if writefile then
        local exists = false
        if isfile then
            exists = isfile(imageFile)
        end
        if not exists then
            writefile(imageFile, VXZBase64Decode(VXZHomeImageData))
        end
    end
    if getcustomasset then
        VXZHomeImage = getcustomasset(imageFile)
    elseif getsynasset then
        VXZHomeImage = getsynasset(imageFile)
    end
end)

local HomeTab = Window:MakeTab({Title = "Home", Icon = "home"})
HomeTab:AddImage({
    Image = VXZHomeImage,
    Height = 205,
    Title = "VXZ SCRIPT"
})

HomeTab:AddButton({
    Title = "Copy Link Discord Vxz Script",
    Description = "Copy Discord chính thức của VXZ Script",
    Callback = function()
        local link = "https://discord.gg/4HjWdNpVx"
        local copied = false
        pcall(function()
            if setclipboard then
                setclipboard(link)
                copied = true
            elseif toclipboard then
                toclipboard(link)
                copied = true
            end
        end)
        pcall(function()
            Alurt.CreateNode({
                Title = copied and "ĐÃ COPY LINK DISCORD" or "DISCORD VXZ SCRIPT",
                Content = copied and "HÃY VÀO DISCORD ĐỂ NHẬN THÔNG BÁO CẬP NHẬT SCRIPT" or link,
                Audio = "rbxassetid://17208361335",
                Length = 5,
                Image = "rbxassetid://6031068421",
                BarColor = Color3.fromRGB(0, 200, 180)
            })
        end)
    end
})

pcall(function()
    local old = CoreGui:FindFirstChild("VXZ_Floating_Button")
    if old then old:Destroy() end

    local FloatGui = Instance.new("ScreenGui")
    FloatGui.Name = "VXZ_Floating_Button"
    FloatGui.ResetOnSpawn = false
    FloatGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    FloatGui.Parent = CoreGui

    local FloatButton = Instance.new("TextButton")
    FloatButton.Name = "VXZ"
    FloatButton.Parent = FloatGui
    FloatButton.Size = UDim2.fromOffset(60, 60)
    FloatButton.Position = UDim2.new(0, 20, 0.5, -30)
    FloatButton.BackgroundColor3 = Color3.fromRGB(255, 105, 180)
    FloatButton.Text = "Vxz"
    FloatButton.TextColor3 = Color3.fromRGB(0, 255, 210)
    FloatButton.Font = Enum.Font.GothamBlack
    FloatButton.TextSize = 20
    FloatButton.AutoButtonColor = true
    FloatButton.Active = true

    local Corner = Instance.new("UICorner")
    Corner.CornerRadius = UDim.new(0, 12)
    Corner.Parent = FloatButton

    local Stroke = Instance.new("UIStroke")
    Stroke.Color = Color3.fromRGB(0, 255, 210)
    Stroke.Thickness = 2
    Stroke.Parent = FloatButton

    local Gradient = Instance.new("UIGradient")
    Gradient.Rotation = 45
    Gradient.Color = ColorSequence.new(
        Color3.fromRGB(255, 80, 170),
        Color3.fromRGB(255, 150, 210)
    )
    Gradient.Parent = FloatButton

    local dragging, dragStart, startPos
    FloatButton.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = true
            dragStart = input.Position
            startPos = FloatButton.Position
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseMovement) then
            local delta = input.Position - dragStart
            if delta.Magnitude > 8 then
                FloatButton.Position = UDim2.new(
                    startPos.X.Scale, startPos.X.Offset + delta.X,
                    startPos.Y.Scale, startPos.Y.Offset + delta.Y
                )
            end
        end
    end)
    UserInputService.InputEnded:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
            dragging = false
        end
    end)

    local lastClick = 0
    FloatButton.Activated:Connect(function()
        local now = os.clock()
        if now - lastClick < 0.15 then return end
        lastClick = now
        local rotation = TweenService:Create(
            FloatButton,
            TweenInfo.new(0.45, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),
            {Rotation = FloatButton.Rotation + 360}
        )
        rotation:Play()
        rotation.Completed:Connect(function()
            FloatButton.Rotation = 0
        end)
        Window:Minimize()
    end)
end)

local MainTab = Window:MakeTab({Title = "Main", Icon = "home"})
MainTab:AddToggle({
    Title = "Instant Prompt Egg",
    Description = "Kích hoạt Prompt Egg nhanh",
    Default = false,
    Callback = function(value)
        Config.InstantEgg = value
        if value then StartInstantEgg() else StopInstantEgg() end
        NotifyFeature("Instant Prompt Egg", value)
    end
})

MainTab:AddToggle({
    Title = "Auto Steal Best Egg (High Value)",
    Description = "Tự động tìm trứng giá trị cao và quay về nhà",
    Default = false,
    Callback = function(value)
        Config.AutoStealBest = value
        if value then
            if not Config.Godmode then EnableGodmode() end
            StartAutoStealLoop()
        else
            StopAutoStealLoop()
        end
        NotifyFeature("Auto Steal Best Egg", value)
    end
})

local SpeedTab = Window:MakeTab({Title = "Speed Player", Icon = "shield-check"})
SpeedTab:AddToggle({
    Title = "Speed Boost",
    Description = "Bật chế độ tăng tốc độ",
    Default = false,
    Callback = function(value)
        if value then EnableGodmode() else DisableGodmode() end
        NotifyFeature("Speed Boost", value)
    end
})

