local HopServerTab = Window:MakeTab({Title = "Hop Server", Icon = "server"})
local TeleportService = game:GetService("TeleportService")
local HttpService = game:GetService("HttpService")
local HopServerBusy = false

local function GetPublicServers()
    local servers, cursor, pages = {}, nil, 0
    repeat
        pages += 1
        local url = "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Asc&limit=100"
        if cursor then url ..= "&cursor=" .. HttpService:UrlEncode(cursor) end
        local ok, response = pcall(function() return game:HttpGet(url) end)
        if not ok or not response then break end
        local decodedOk, data = pcall(function() return HttpService:JSONDecode(response) end)
        if not decodedOk or not data then break end
        for _, server in ipairs(data.data or {}) do
            if server.id and server.id ~= game.JobId and server.playing and server.maxPlayers and server.playing < server.maxPlayers then
                table.insert(servers, server)
            end
        end
        cursor = data.nextPageCursor
    until not cursor or pages >= 5
    return servers
end

HopServerTab:AddButton({
    Title = "Hop Server New",
    Description = "Đổi sang một server công khai khác",
    Callback = function()
        if HopServerBusy then return end
        HopServerBusy = true
        local ok, err = pcall(function()
            local servers = GetPublicServers()
            if #servers == 0 then error("Không tìm thấy server khác") end
            local target = servers[math.random(1, #servers)]
            TeleportService:TeleportToPlaceInstance(game.PlaceId, target.id, LocalPlayer)
        end)
        if not ok then warn("Hop Server New lỗi:", err); HopServerBusy = false end
    end
})

