        local RefreshBtn = Instance.new("TextButton")
        RefreshBtn.Parent = MainFrame
        RefreshBtn.BackgroundColor3 = Color3.fromRGB(22, 22, 22)
        RefreshBtn.BorderColor3 = Color3.fromRGB(0, 255, 120)
        RefreshBtn.Position = UDim2.new(0.52, 0, 0.54, 0)
        RefreshBtn.Size = UDim2.new(0.43, 0, 0, 28)
