        local HopBtn = Instance.new("TextButton")
        HopBtn.Parent = MainFrame
        HopBtn.BackgroundColor3 = Color3.fromRGB(20, 20, 20)
        HopBtn.BorderColor3 = Color3.fromRGB(0, 255, 120)
        HopBtn.Position = UDim2.new(0.05, 0, 0.82, 0)
        HopBtn.Size = UDim2.new(0.9, 0, 0, 28)
        HopBtn.Font = Enum.Font.Code
        HopBtn.Text = "SERVER HOP NOW"
        HopBtn.TextColor3 = Color3.fromRGB(0, 255, 120)
        HopBtn.TextSize = 11
        HopBtn.MouseButton1Click:Connect(function()
            pcall(function()
                StatusLabel.Text = "SEARCHING..."
                task.wait(0.2)
                local servers = {}
                local url = "https://games.roblox.com/v1/games/" .. tostring(game.PlaceId) .. "/servers/Public?sortOrder=Asc&limit=100"
                local req = HttpService:JSONDecode(game:HttpGet(url))
                if req and req.data then
                    for _, s in pairs(req.data) do
                        if s and s.playing and s.maxPlayers and s.id ~= game.JobId and s.playing < s.maxPlayers then
                            if selectedTarget == 999 or s.playing <= selectedTarget then
                                table.insert(servers, s.id)
                            end
                        end
                    end
                end
                if #servers > 0 then
                    StatusLabel.Text = "JOINING..."
                    TeleportService:TeleportToPlaceInstance(game.PlaceId, servers[math.random(1, #servers)], LocalPlayer)
                else
                    StatusLabel.Text = "No matching server found!"
                end
            end)
        end)
